head.script:
///////// 2. 초기화 영역 /////////
/* ★Wcraft guide★    
스크립트 수작업 유의사항

*/
/**
 * @method
 * @name onpageload
 * @description 화면 진입점 — 페이지 로드 이벤트 핸들러(현재 별도 초기화 로직 없음).
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageload 바인딩으로 자동 호출)
 */
scwin.onpageload = function() {
};

/**
 * @method
 * @name onpageunload
 * @description 화면 종료 시 호출되는 페이지 언로드 이벤트 핸들러(현재 별도 정리 로직 없음).
 * @returns {void}
 * @hidden N
 * @example (body ev:onpageunload 바인딩으로 자동 호출)
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name MxDataSet_OnLoadCompleted
 * @description MxDataSet 조회 완료 콜백 — 조회 결과 총 건수를 textbox_1에 표시한다.
 * @param {Object} e 서브미션 완료 이벤트/결과 객체
 * @returns {void}
 * @hidden N
 * @example scwin.MxDataSet_OnLoadCompleted(e);
 */
scwin.MxDataSet_OnLoadCompleted = function(e) {
    try {
        textbox_1.setValue("총 " + rowcount + "건");
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80209.MxDataSet_OnLoadCompleted" });
    }
};

/**
 * @method
 * @name btn_cal_onclick
 * @description [달력] 버튼 클릭 — 기준일자 입력(txb_date)용 달력 팝업(popUpCalendar)을 연다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_cal_onclick(e);
 */
scwin.btn_cal_onclick = function(e) {
    try {
        popUpCalendar(txb_date_bg, 'txb_date', 'yyyymmdd'); // alert('image_2.onclick');
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80209.btn_cal_onclick" });
    }
};

/**
 * @method
 * @name btn_sys_search_onclick
 * @description [조회] 버튼 클릭 — 기준일자(txb_date) 입력 여부를 확인한 후 전문수신로그 목록을 조회한다(listSync).
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_sys_search_onclick(e);
 */
scwin.btn_sys_search_onclick = function(e) {
    try {
        if (txb_date.Text !== "") {
            scwin.listSync(); // alert();

        } else {
            alert("일자를 지정하십시요");
        }
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80209.btn_sys_search_onclick" });
    }
};

/**
 * @method
 * @name btn_toExcel_onclick
 * @description [엑셀다운로드] 버튼 클릭 — 그리드(MxGrid_1) 데이터를 '코스닥매매시스템전문수신로그' 엑셀 파일로 내려받는다.
 * @param {Object} e 이벤트 객체
 * @returns {void}
 * @hidden N
 * @example scwin.btn_toExcel_onclick(e);
 */
scwin.btn_toExcel_onclick = function(e) {
    try {
        $c.data.downloadGridViewExcel(MxGrid_1, {fileName: "코스닥매매시스템전문수신로그", type: "8"});
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80209.btn_toExcel_onclick" });
    }
};

/**
 * @method
 * @name MxDataSet_tempdepo_OnLoadCompleted
 * @description MxDataSet_tempdepo(제출확인) 조회 완료 콜백(현재 별도 처리 로직 없음).
 * @param {Object} e 서브미션 완료 이벤트/결과 객체
 * @returns {void}
 * @hidden N
 * @example scwin.MxDataSet_tempdepo_OnLoadCompleted(e);
 */
scwin.MxDataSet_tempdepo_OnLoadCompleted = function(e) {

};

/**
 * @method
 * @name MxGrid_1_OnClick
 * @description 그리드 행 클릭 — 클릭 행의 구분(GB2) 값으로 제출확인 목록을 조회한다(listSync2).
 * @param {Number} row 클릭한 행 인덱스
 * @param {String} colid 클릭한 컬럼 id
 * @returns {void}
 * @hidden N
 * @example scwin.MxGrid_1_OnClick(0, "GB2");
 */
scwin.MxGrid_1_OnClick = function(row, colid) {
    try {
        const sCd = MxDataSet.getCellData(row, "GB2");
        // alert(sCd);
        scwin.listSync2(sCd);
    } catch (ex) {
        $c.exception.handleError(ex, { context : "ULDMGT80209.MxGrid_1_OnClick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name listSync
 * @description 전문수신로그 목록 조회 서브미션 — /kosdaqtrdlog.do 를 호출해 MxDataSet을 갱신하고 구 콜백(MxDataSet_OnLoadCompleted)을 연결한다.
 * @returns {Promise<void>}
 * @hidden N
 * @example scwin.listSync();
 */
scwin.listSync = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/kosdaqtrdlog.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_OnLoadCompleted(sbmRtn); // 구 콜백 연결

};

/**
 * @method
 * @name listSync2
 * @description 제출확인 목록 조회 서브미션 — 신청번호 조건으로 /tempdepo.do 를 호출해 MxDataSet_tempdepo를 갱신하고 구 콜백을 연결한다.
 * @param {String} sval 신청번호(APPL_NO) 조건 값
 * @returns {Promise<void>}
 * @hidden N
 * @example scwin.listSync2(sCd);
 */
scwin.listSync2 = async function(sval) {
    // discls_acpt_monitor.xml 참조
    const cdCase1 = "&ACPT_APPL_TP_CD=";
    const cdCase2 = "&DISCLS_ACPT_TP_CD=";
    const cdCase3 = "&LD_MKT_TP_CD=";
    const cdCase4 = "&DISCLS_SUBMIT_CORP_ISUR_CD=";
    const cdCase5 = "&APPL_NO=" + sval;
    const sbmOptions = {
        id : "sbm_MxDataSet_tempdepo",
        action : "/tempdepo.do",
        ref : "",
        target : "MxDataSet_tempdepo=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_tempdepo_OnLoadCompleted(sbmRtn); // 구 콜백 연결

};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name gform_onload
 * @description 구 Gauce gform onload 이관 함수 — 목록·제출확인 데이터셋 초기 조회 후 오늘 일자 설정(toDaySet)을 수행한다.
 * @returns {Promise<void>}
 * @hidden N
 * @example scwin.gform_onload();
 */
scwin.gform_onload = async function() {
    const sbmOptions = {
        id : "sbm_MxDataSet",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    scwin.MxDataSet_OnLoadCompleted(sbmRtn); // 구 콜백 연결

    const sbmOptions2 = {
        id : "sbm_MxDataSet_tempdepo",
        action : "/gauceSystemierAdaptor.do",
        ref : "",
        target : "MxDataSet_tempdepo=body.content",
        isProcessMsg : false
    };

    const sbmRtn2 = await $c.sbm.executeDynamic(sbmOptions2);
    scwin.MxDataSet_tempdepo_OnLoadCompleted(sbmRtn2); // 구 콜백 연결

    // PanelToGroupBox_02(panel_2);

    toDaySet(txb_date);
};
